// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(this));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }

        // Deploy a helper that accepts the transferFrom call without reverting.
        // This ensures the low-level call in C.transfer succeeds.
        SuccessfulCallee helper = new SuccessfulCallee();

        bool success;
        try c.transfer(from, address(helper), _tos, v) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }

        // The invariant: if the call completes (no revert), the return value must be true.
        // The buggy version completes but returns false, violating this.
        assertTrue(success);
    }
}

// Adversarial helper that implements the expected transferFrom interface
// and always succeeds, so the call inside C.transfer doesn't revert.
contract SuccessfulCallee {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Deploy helper that always returns true on transferFrom
        TransferFromHelper helper = new TransferFromHelper();
        // Use helper address as caddress
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSelector(C.transfer.selector, from, address(helper), _tos, v));
        require(success, "call failed");
        bool returned = abi.decode(ret, (bool));
        assertTrue(returned);
    }
}

contract TransferFromHelper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
